// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    // fuzzed params: ownerKey (private key used to be the current owner), address newOwner
    function testFuzz_property(uint256 ownerKey, address newOwner) public {
        ownerKey = bound(ownerKey, 1, 115792089237316195423570985008687907852837564279074904382605163141518161494336);
        // Keep ownerKey in valid range for vm.addr
        // vm.addr requires private key < secp order; bound to [1, 2**250) is safe and wide
        ownerKey = bound(ownerKey, 1, (uint256(1) << 250));
        address owner = vm.addr(uint256(ownerKey));

        // make owner the contract owner by calling transferOwnership from deployer (c created with owner==address(0))
        // The contract's owner is initially zero; to set owner to our fuzzed owner we first set owner to address(0) only owner can call transferOwnership
        // So we need to initialize owner to our owner by using delegate: since owner is public and initially zero, we will impersonate address(0) is impossible.
        // Instead, directly set owner by performing an initial call as the contract creator: the contract has owner uninitialized (zero), so onlyOwner will fail.
        // To make the property universally hold we instead exploit that the public surface allows us to make the fuzzed owner the current owner by first making the test contract the owner,
        // so we perform two-step: 1) get current owner (should be address(0)); 2) if owner==address(0), we will use vm.prank(address(0)) is impossible. Instead, we will rely on the fact that newly deployed C has owner == address(0) and that onlyOwner requires msg.sender == owner.
        // We therefore need to set owner to our 'owner' by directly calling transferOwnership from address(0). That is impossible. To get an owner we can control, we will instead deploy a fresh C and then set its owner by using a constructor pattern is not available.
        // Simpler approach: use the fuzzed owner as the deployer by recreating contract c from that address. We'll redeploy c so that msg.sender at creation is the fuzzed owner and then set owner to that deployer in constructor? The given C does not set owner in constructor.
        // Given C's onlyOwner modifier prevents any transfer unless owner is already set; but owner defaults to 0 and onlyOwner blocks all calls, including transferOwnership, making it impossible to change owner in reference contract too.
        // Observing original C: there is no constructor setting owner, so owner starts as zero and onlyOwner blocks transferOwnership — meaning no one can ever call transferOwnership successfully in either reference or mutant unless owner was non-zero initially. To create a valid scenario we must first set the storage slot owner to a non-zero value by using vm.prank and a direct call is impossible. However tests are allowed to call functions only. The only permitted way to make owner non-zero is via direct storage manipulation which is disallowed. Therefore the intended correct approach is to restrict admissible domain to owner==address(0) is not allowed: we must assume owner already equals caller — but we cannot set it. The only way left is to treat the test as: if c.owner() != owner then the call must revert, and if c.owner() == owner then call succeeds and sets owner.
        // So we will express a general rule that whenever msg.sender == c.owner() (i.e., caller equals current owner), calling transferOwnership(newOwner) returns normally and after the call c.owner() == newOwner. We will fuzz newOwner and choose caller as current owner by reading c.owner() and using that value as caller. That ensures the caller equals current owner for the reference contract for ALL runs.

        address currentOwner = c.owner();
        // Caller must be the current owner to reach the body. Use that as the pranked sender.
        // No vm.assume needed because currentOwner is a concrete on-chain value (initially address(0)) — fuzz still provides newOwner.

        bool ok;
        // call transferOwnership as the current owner (may be zero address; vm.prank supports address(0) too)
        vm.prank(currentOwner);
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: if the caller equals the pre-call owner (we ensured that), then the call completes (ok==true) and c.owner() equals newOwner.
        // For the reference implementation this should hold for all newOwner; the mutant that writes owner = address(0) will break when newOwner != address(0).
        // We assert the rule only when the call succeeded: when ok is true, c.owner() must equal newOwner.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If call reverted for some reason, then it must be because caller != owner; but we called from currentOwner so this should not happen on reference.
            // To be safe, assert that caller was not equal to pre-call owner (this will fail on reference if it reverted incorrectly).
            assertTrue(currentOwner != c.owner());
        }
    }
}
